def transform(wb):
    ws = wb["Sheet1"]
    i_values = []
    for r in range(1, 3708):
        v = ws.cell(row=r, column=9).value
        if v is not None and v != "":
            i_values.append(v)
    keep = []
    for r in range(1, 1103):
        a = ws.cell(row=r, column=1).value
        if a is None or a == "":
            keep.append(r)
        else:
            match = False
            for iv in i_values:
                if a == iv:
                    match = True
                    break
            if not match:
                keep.append(r)
    out = 1
    for r in keep:
        for c in range(1, 6):
            ws.cell(row=out, column=c).value = ws.cell(row=r, column=c).value
        out += 1
    for r in range(out, 1103):
        for c in range(1, 6):
            ws.cell(row=r, column=c).value = None
